"use client";

/**
 * StageTabs — pestañas de etapas con contador de novedades (Mi Garaje, /blocks/mi-garaje/m/vmc: las 4 etapas de Mis
 * participaciones). Forma de carpeta, la misma de FolderTabs: la elegida es una tarjeta blanca unida a la lista y su fondo
 * (un único elemento de framer-motion) se desliza al cambiar. El número de novedades va entre paréntesis detrás del texto.
 * Depende de React, framer-motion, TabSelector (clases ptabs) y FolderTabs (forma de carpeta).
 */
import { useId } from "react";
import type { JSX } from "react";
import { motion } from "framer-motion";
import { TABSELECTOR_STYLES } from "@/concorde/components/TabSelector";
import { FOLDER_TABS_CSS } from "@/concorde/components/FolderTabs";

export const STAGE_TABS_CSS = String.raw`
.fs__split--stages::before { z-index:0; }
.fs__split--stages .ptabs { overflow:visible; cursor:default; -webkit-mask:none; mask:none; border-bottom-color:transparent; }
.fs__split--stages .ptabs__tab, .fs__split--stages .ptabs__tab:not(.ptabs__tab--active), .fs__split--stages .ptabs__tab--active { position:relative; isolation:isolate; display:inline-flex; align-items:center; flex-direction:row; flex-wrap:nowrap;
  flex:1 1 0; min-width:0; min-height:40px; padding:6px 4px; font-size:11px; gap:0 2px; }
.fs__split--stages .ptabs__tab--active { flex:1.35 1 0; z-index:2; overflow:visible; margin-bottom:0; background:#fff; border-color:transparent; border-bottom:1px solid #fff; box-shadow:none; }
.fs__split--stages .ptabs__tab--active::after { content:""; position:absolute; z-index:2; left:-1px; right:-1px; bottom:-2px; height:3px; background:#fff; pointer-events:none; }
.fs__split--stages .ptabs__tab > :not(.st__active-bg) { position:relative; z-index:1; }
/* Número entre paréntesis detrás del texto. */
.fs__split--stages .st__n { order:2; flex:none; display:inline; width:auto; height:auto; padding:0; border-radius:0; background:none; color:inherit; -webkit-text-fill-color:inherit; font-size:inherit; font-weight:inherit; line-height:inherit; }
.fs__split--stages .st__n::before { content:"("; } .fs__split--stages .st__n::after { content:")"; }
.fs__split--stages .st__t { min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.fs__split--stages .ptabs__tab--active .st__t { overflow:visible; text-overflow:clip; }
/* Fondo de la elegida: la tarjeta blanca de la carpeta, un solo elemento que se desliza entre pestañas. */
.st__active-bg { position:absolute; inset:0 0 -1px; z-index:0; border:1px solid #DCD2FB; border-bottom-color:#fff; border-radius:10px 10px 0 0; background:#fff; box-shadow:0 -3px 8px rgba(34,0,92,.05); }
`;

export interface StageTabsProps {
  /** Nombres de las etapas, en el orden en que se muestran. */
  labels: string[];
  /** Novedades sin abrir por etapa (mismo orden que `labels`). Con 0 la pestaña va en peso normal y sin número. */
  counts: number[];
  /** Índice de la etapa elegida. */
  value: number;
  /** Se llama con el índice de la etapa tocada. */
  onChange: (index: number) => void;
  /** Nombre accesible del grupo de pestañas. */
  ariaLabel?: string;
  /** layoutId de framer-motion para el fondo de la activa (por defecto, uno propio de cada instancia). */
  layoutId?: string;
}

export function StageTabs({ labels, counts, value, onChange, ariaLabel = "Etapas", layoutId }: StageTabsProps): JSX.Element {
  const ownId = useId();
  const activeId = layoutId ?? `stage-tabs-${ownId}`;
  return <>
    <style href="concorde-tabselector" precedence="default">{TABSELECTOR_STYLES}</style>
    <style href="concorde-folder-tabs" precedence="default">{FOLDER_TABS_CSS}</style>
    <style href="concorde-stage-tabs" precedence="default">{STAGE_TABS_CSS}</style>
    <div className="fs__split fs__split--stages">
      <div className="ptabs" role="tablist" aria-label={ariaLabel}>
        {labels.map((label, i) => <button key={label} type="button" role="tab" aria-selected={value === i} className={`ptabs__tab${value === i ? " ptabs__tab--active" : ""}${counts[i] > 0 ? " ptabs__tab--unread" : " ptabs__tab--read"}`}
          style={{ viewTransitionName: `stage-${label.toLowerCase().replaceAll(" ", "-")}` }}
          onClick={() => onChange(i)}>
          {value === i ? <motion.span layoutId={activeId} className="st__active-bg" transition={{ type: "spring", stiffness: 420, damping: 34, mass: .7 }} /> : null}
          {counts[i] > 0 ? <span className="st__n">{counts[i]}</span> : null}<span className="st__t">{label}</span></button>)}
      </div>
    </div>
  </>;
}

export default StageTabs;

"use client";

/**
 * TabSelector — Generado por Concorde
 * Fuente: Figma VOYAGER · "RadioGroup" (nodo 3008:15095)
 *
 * Selector tipo segmented/tab: contenedor pill blanco (radio 24.5, borde
 * gradiente #8460E5 → #FFF8F1) con N opciones. La opción activa lleva relleno
 * gradiente oscuro (#8460E5 → #3B1782), borde gradiente (white → #F4AC59 →
 * #8460E5 → white), texto blanco y sombra; las inactivas llevan texto en
 * gradiente lila (#8460E5 → #3B1782). Controlado o no controlado.
 */

import { useId, useState } from "react";
import type { JSX } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface TabSelectorProps {
  /** Etiquetas de las opciones */
  options: string[];
  /** Índice activo (controlado, 0-based) */
  value?: number;
  /** Índice inicial (no controlado, default 0) */
  defaultValue?: number;
  /** Callback al cambiar de opción */
  onChange?: (index: number) => void;
  "aria-label"?: string;
  className?: string;
  /** Modo bandeja (Mi Garaje): las opciones con novedades sin abrir van en bold y el resto en peso normal.
   *  Sin esta prop todas las pestañas conservan su peso de siempre. */
  notificationIndices?: number[];
}

// ─── Self-contained CSS ───────────────────────────────────────────────────────

const STYLE_ID = "concorde-tabselector-styles";

export const TABSELECTOR_STYLES = `
.ptabs {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 49px;
  padding: 0 7px;
  border-radius: 24.5px;
  border: 1px solid transparent;
  background-image: linear-gradient(#ffffff, #ffffff), linear-gradient(330deg, #8460E5 0%, #FFF8F1 100%);
  background-origin: border-box;
  background-clip: padding-box, border-box;
  font-family: var(--vmc-font-display, "Plus Jakarta Sans", -apple-system, sans-serif);
}
.ptabs__tab {
  appearance: none;
  box-sizing: border-box;
  min-width: 83px;
  height: 34px;
  padding: 0 16px;
  border: 2px solid transparent;
  border-radius: 17px;
  white-space: nowrap;
  background: transparent;
  font-family: inherit;
  font-size: 12px;
  font-weight: 600;
  line-height: 16px;
  cursor: pointer;
  /* inactivo: texto en gradiente lila */
  color: #3B1782;
  background-image: linear-gradient(135deg, #8460E5 0%, #3B1782 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  transition: transform 0.16s, box-shadow 0.2s, opacity 0.16s;
}
.ptabs__tab:hover { opacity: 0.78; }
.ptabs__tab:active { transform: scale(0.97); }
.ptabs__tab:focus-visible { outline: 2px solid #8460E5; outline-offset: 2px; }
.ptabs__tab--active {
  color: #ffffff;
  -webkit-text-fill-color: #ffffff;
  background-image:
    linear-gradient(150deg, #8460E5 0%, #3B1782 100%),
    linear-gradient(120deg, #ffffff 0%, #F4AC59 22%, #8460E5 75%, #ffffff 100%);
  background-origin: border-box;
  background-clip: padding-box, border-box;
  box-shadow: rgba(34, 0, 92,0.2) 0px 8px 16px;
}
.ptabs__tab--active:hover { opacity: 1; }
/* Modo bandeja: la diferencia se lee de inmediato, aun en tamaños pequeños. */
.ptabs__tab--unread { font-weight: 800 !important; letter-spacing: -0.012em; color: #2A075E; }
.ptabs__tab--read { font-weight: 400 !important; }
.ptabs__tab--read:not(.ptabs__tab--active) { color: #6B6878; background-image: none; -webkit-text-fill-color: #6B6878; opacity: 1; }
@media (prefers-reduced-motion: reduce) {
  .ptabs__tab { transition: none; }
}
`;

let _stylesInjected = false;

// ─── Component ────────────────────────────────────────────────────────────────

export default function TabSelector({
  options,
  value,
  defaultValue = 0,
  onChange,
  "aria-label": ariaLabel,
  className = "",
  notificationIndices,
}: TabSelectorProps): JSX.Element {
  const uid = useId().replace(/:/g, "-");
  const controlled = value !== undefined;
  const [internal, setInternal] = useState(defaultValue);
  const active = controlled ? value : internal;

  function select(i: number): void {
    if (!controlled) setInternal(i);
    onChange?.(i);
  }

  if (typeof document !== "undefined" && !_stylesInjected) {
    if (!document.getElementById(STYLE_ID)) {
      const el = document.createElement("style");
      el.id = STYLE_ID;
      el.textContent = TABSELECTOR_STYLES;
      document.head.appendChild(el);
    }
    _stylesInjected = true;
  }

  return (
    <>
      <style id={`${STYLE_ID}-ssr`} suppressHydrationWarning dangerouslySetInnerHTML={{ __html: TABSELECTOR_STYLES }} />
      <div className={["ptabs", className].filter(Boolean).join(" ")} role="tablist" aria-label={ariaLabel}>
        {options.map((label, i) => {
          const isActive = i === active;
          return (
            <button
              key={`${uid}-${i}`}
              type="button"
              role="tab"
              aria-selected={isActive}
              className={["ptabs__tab", isActive ? "ptabs__tab--active" : "",
                notificationIndices ? (notificationIndices.includes(i) ? "ptabs__tab--unread" : "ptabs__tab--read") : ""].filter(Boolean).join(" ")}
              onClick={function pick() { select(i); }}
            >
              {label}
            </button>
          );
        })}
      </div>
    </>
  );
}

"use client";

/**
 * FolderTabs — pestañas de carpeta de Mi Garaje (/blocks/mi-garaje/m/vmc · Mis negociaciones: «Compras» y «En venta»).
 * Es el TabSelector de Concorde con forma de carpeta: la elegida es una tarjeta blanca con borde lila arriba y a los lados,
 * unida a la lista de abajo; las demás van en gris sobre una línea. Un punto o un número entre paréntesis marca lo que
 * está sin abrir. StageTabs usa la misma forma (FOLDER_TABS_CSS).
 * Depende de React y TabSelector.
 */
import type { JSX } from "react";
import TabSelector from "@/concorde/components/TabSelector";

/** Forma de carpeta sobre las clases de TabSelector (ptabs). La comparten FolderTabs y StageTabs (.fs__split--stages). */
export const FOLDER_TABS_CSS = String.raw`
.fs__split { position:relative; display:grid; min-width:0; padding:0 0 12px; }
.fs__split::before { content:""; position:absolute; left:0; right:0; bottom:12px; height:1px; background:#DCD2FB; }
.fs__split .ptabs { position:relative; z-index:1; display:flex; align-items:flex-end; gap:2px; width:100%; min-width:0; box-sizing:border-box; height:auto; padding:0 4px; border:0; border-radius:0; background:none; overflow:hidden; }
.fs__split .ptabs__tab { flex:1 1 auto; width:auto; min-width:0; height:auto; min-height:40px; margin-bottom:0; padding:6px 8px; justify-content:center; text-align:center; border:1px solid transparent; border-bottom:0; border-radius:10px 10px 0 0;
  background:none; color:#6B6878; -webkit-text-fill-color:#6B6878; font-weight:600; white-space:nowrap; line-height:1.2; text-wrap-style:balance; }
.fs__split .ptabs__tab--active { flex:none; background:#fff; border-color:#DCD2FB; border-bottom:1px solid #fff; box-shadow:0 -3px 8px rgba(34,0,92,.05); color:#3B1782; -webkit-text-fill-color:#3B1782; font-weight:700; }
.fs__split .ptabs__tab:not(.ptabs__tab--active) { flex:1 1 0; }
.fs__split:not(.fs__split--stages) .ptabs__tab, .fs__split:not(.fs__split--stages) .ptabs__tab--active { flex:1 1 0; }
/* Con novedades sin abrir: en negrita (como en el lab; TabSelector de Concorde aún no lo trae). */
.fs__split .ptabs__tab--unread { font-weight:800 !important; letter-spacing:-0.012em; color:#2A075E; }
.fs__split .ptabs__tab:hover { opacity:1; }
`;

export interface FolderTabsProps {
  /** Textos de las pestañas, con su número entre paréntesis si lo hay (p. ej. «Compras», «En venta (1)»). */
  options: string[];
  /** Índice de la pestaña elegida. */
  value: number;
  /** Se llama con el índice de la pestaña tocada. */
  onChange: (index: number) => void;
  /** Pestañas con novedades sin abrir (van en negrita). */
  notificationIndices?: number[];
  /** Nombre accesible del grupo de pestañas. */
  "aria-label"?: string;
}

export function FolderTabs({ options, value, onChange, notificationIndices, "aria-label": ariaLabel }: FolderTabsProps): JSX.Element {
  return <>
    <style href="concorde-folder-tabs" precedence="default">{FOLDER_TABS_CSS}</style>
    <div className="fs__split"><TabSelector options={options} notificationIndices={notificationIndices} value={value} onChange={onChange} aria-label={ariaLabel} /></div>
  </>;
}

export default FolderTabs;
